/**
 * Pure helpers for building HC Discovery Run field sets. Time values are
 * plain epoch-millisecond numbers, not formatted date strings - keeps this
 * module honestly platform-agnostic. The platform-side wrapper (Phase 2+)
 * is responsible for converting to/from GlideDateTime (see the epoch-millis
 * handling already proven in servicenow/event-management/webhook-scripted-rest.js).
 */

var MAX_ERROR_SUMMARY_LENGTH = 4000;

/**
 * @param {{accountSysId: string, regionSysId: string, resourceType: string, correlationId?: string, traceId?: string, dryRun?: boolean, startedAtMs: number}} args
 */
function startRun(args) {
  if (!args || !args.accountSysId) throw new Error('accountSysId is required');
  if (!args.regionSysId) throw new Error('regionSysId is required');
  if (!args.resourceType) throw new Error('resourceType is required');
  if (args.startedAtMs == null) throw new Error('startedAtMs is required');

  return {
    account: args.accountSysId,
    region: args.regionSysId,
    resource_type: args.resourceType,
    state: 'running',
    started_at_ms: args.startedAtMs,
    ended_at_ms: null,
    success_count: 0,
    fail_count: 0,
    error_summary: null,
    correlation_id: args.correlationId || null,
    trace_id: args.traceId || null,
    dry_run: !!args.dryRun
  };
}

/**
 * @param {ReturnType<typeof startRun>} runFields
 * @param {{successCount: number, failCount: number, errorSummary?: string, endedAtMs: number}} outcome
 */
function finishRun(runFields, outcome) {
  if (!runFields) throw new Error('runFields is required');
  if (!outcome || outcome.endedAtMs == null) throw new Error('endedAtMs is required');

  var successCount = outcome.successCount || 0;
  var failCount = outcome.failCount || 0;
  // A run that fails before any per-item counting happens (e.g. a fetch
  // throwing on the very first call) reports successCount:0, failCount:0 -
  // errorSummary is the only signal that it wasn't actually a no-op success,
  // so it must also flip the state to 'failed', not just failCount alone.
  var state = (successCount === 0 && (failCount > 0 || !!outcome.errorSummary)) ? 'failed' : 'completed';

  var summary = outcome.errorSummary || null;
  if (summary && summary.length > MAX_ERROR_SUMMARY_LENGTH) {
    summary = summary.slice(0, MAX_ERROR_SUMMARY_LENGTH);
  }

  var result = {};
  for (var k in runFields) { if (Object.prototype.hasOwnProperty.call(runFields, k)) result[k] = runFields[k]; }
  result.state = state;
  result.ended_at_ms = outcome.endedAtMs;
  result.success_count = successCount;
  result.fail_count = failCount;
  result.error_summary = summary;
  return result;
}

/**
 * @param {ReturnType<typeof finishRun>} runFields
 * @returns {{total: number, successRate: number|null, durationMs: number|null}}
 */
function summarizeRun(runFields) {
  var total = (runFields.success_count || 0) + (runFields.fail_count || 0);
  var durationMs = null;
  if (runFields.ended_at_ms != null && runFields.started_at_ms != null) {
    durationMs = runFields.ended_at_ms - runFields.started_at_ms;
  }
  return {
    total: total,
    successRate: total === 0 ? null : runFields.success_count / total,
    durationMs: durationMs
  };
}

/**
 * Maps startRun()/finishRun() output onto the exact field names declared in
 * tables/hc_discovery_run.schema.json (`started`/`ended`, not
 * `started_at_ms`/`ended_at_ms`) - the internal `_at_ms` names exist only
 * to keep this module's own math unambiguous. The returned `started`/`ended`
 * values are STILL epoch-millisecond numbers, not GlideDateTime objects or
 * formatted strings - the ServiceNow-side platform wrapper must still run
 * them through `GlideDateTime.setNumericValue()` before assigning to the
 * GlideRecord field, exactly like the already-proven pattern in
 * servicenow/event-management/webhook-scripted-rest.js's time handling.
 * @param {ReturnType<typeof startRun>|ReturnType<typeof finishRun>} runFields
 * @returns {{account: string, region: string, resource_type: string, state: string, started: number, ended: number|null, success_count: number, fail_count: number, error_summary: string|null, correlation_id: string|null, trace_id: string|null, dry_run: boolean}}
 */
function toServiceNowDiscoveryRunFields(runFields) {
  if (!runFields) throw new Error('runFields is required');
  return {
    account: runFields.account,
    region: runFields.region,
    resource_type: runFields.resource_type,
    state: runFields.state,
    started: runFields.started_at_ms,
    ended: runFields.ended_at_ms != null ? runFields.ended_at_ms : null,
    success_count: runFields.success_count,
    fail_count: runFields.fail_count,
    error_summary: runFields.error_summary,
    correlation_id: runFields.correlation_id,
    trace_id: runFields.trace_id,
    dry_run: runFields.dry_run
  };
}

// ---- inlined from lib/syncStatePlanner.js (do not hand-edit here - edit the source and regenerate) ----
/**
 * Pure planner for HC Resource Sync State writes. Given the resources seen
 * in one discovery run and the existing sync-state rows for that
 * (account, region, resource_type), computes what to insert, what to
 * refresh (seen again), and what lifecycle transition each existing-but-
 * not-seen row should undergo - via resourceLifecycle.computeNextState(),
 * injected as a parameter rather than imported directly, so this module has
 * zero cross-file dependencies (a requirement for
 * scripts/build-script-include.js to safely concatenate it with the other
 * lib modules it inlines).
 *
 * The ServiceNow-side wrapper (service-graph/HcConnectorEcsSync.js) is a
 * thin adapter turning this plan into GlideRecord reads/writes - all the
 * actual decision logic lives here, pure and unit-tested.
 */

/**
 * @param {Array<{native_key: string, ci?: string}>} seenRecords - resources found in this run; ci = the CI sys_id from IRE reconciliation, if known
 * @param {Array<{native_key: string, sys_id: string, status: string, consecutive_miss_count: number}>} existingRows - existing HC Resource Sync State rows for this (account, region, resource_type)
 * @param {{consecutiveMissThreshold?: number, computeNextState: (current: Object, seenThisRun: boolean, threshold?: number) => {status: string, consecutive_miss_count: number}}} options - computeNextState is resourceLifecycle.computeNextState
 * @returns {{toInsert: Array<Object>, toRefresh: Array<Object>, toTransition: Array<Object>}}
 */
function planSyncStateUpdates(seenRecords, existingRows, options) {
  if (!options || typeof options.computeNextState !== 'function') {
    throw new Error('options.computeNextState is required (pass resourceLifecycle.computeNextState)');
  }
  var threshold = options.consecutiveMissThreshold;

  var existingByKey = {};
  (existingRows || []).forEach(function (row) {
    existingByKey[row.native_key] = row;
  });

  var seenByKey = {};
  (seenRecords || []).forEach(function (rec) {
    seenByKey[rec.native_key] = rec;
  });

  var toInsert = [];
  var toRefresh = [];
  var toTransition = [];

  (seenRecords || []).forEach(function (rec) {
    var existing = existingByKey[rec.native_key];
    if (!existing) {
      toInsert.push({ native_key: rec.native_key, ci: rec.ci || null, status: 'active', consecutive_miss_count: 0 });
    } else {
      toRefresh.push({ native_key: rec.native_key, sys_id: existing.sys_id, ci: rec.ci || null, status: 'active', consecutive_miss_count: 0 });
    }
  });

  (existingRows || []).forEach(function (row) {
    if (seenByKey[row.native_key]) return; // already handled as a refresh above
    var next = options.computeNextState(row, false, threshold);
    toTransition.push({
      native_key: row.native_key,
      sys_id: row.sys_id,
      status: next.status,
      consecutive_miss_count: next.consecutive_miss_count,
      justRetired: next.status === 'retired' && row.status !== 'retired'
    });
  });

  return { toInsert: toInsert, toRefresh: toRefresh, toTransition: toTransition };
}

/**
 * @param {ReturnType<typeof planSyncStateUpdates>} plan
 * @returns {{insertCount: number, refreshCount: number, transitionCount: number, newlyRetiredCount: number}}
 */
function summarizePlan(plan) {
  return {
    insertCount: plan.toInsert.length,
    refreshCount: plan.toRefresh.length,
    transitionCount: plan.toTransition.length,
    newlyRetiredCount: plan.toTransition.filter(function (t) { return t.justRetired; }).length
  };
}

var HcConnectorElbSync = Class.create();
HcConnectorElbSync.prototype = {
    initialize: function() {
        this.SCOPE = 'x_2021019_huawei_0';
        this.ACCOUNT_TABLE = this.SCOPE + '_hc_cloud_account';
        this.REGION_TABLE = this.SCOPE + '_hc_cloud_region';
        this.RUN_TABLE = this.SCOPE + '_hc_discovery_run';
        this.SYNC_STATE_TABLE = this.SCOPE + '_hc_resource_sync_state';
        this.CONFIG_TABLE = this.SCOPE + '_hc_connector_config';
        this.RESOURCE_TYPE = 'elb';
    },

    // ------------------------------------------------------------------
    // Entry point
    // ------------------------------------------------------------------
    runAll: function() {
        var self = this;
        var accounts = this._getActiveAccounts();
        gs.info('[HcConnectorElbSync] starting run across ' + accounts.length + ' active account(s)');
        accounts.forEach(function(account) {
            var regions = self._getActiveRegions(account.sys_id);
            regions.forEach(function(region) {
                try {
                    self._runForAccountRegion(account, region);
                } catch (ex) {
                    gs.error('[HcConnectorElbSync] unexpected failure for account=' + account.account_id +
                        ' region=' + region.region + ': ' + ex.message);
                    self._recordRegionError(region.sys_id, ex.message);
                }
            });
        });
        gs.info('[HcConnectorElbSync] run complete');
    },

    _runForAccountRegion: function(account, region) {
        var startedAtMs = new Date().getTime();
        var runFields = startRun({
            accountSysId: account.sys_id,
            regionSysId: region.sys_id,
            resourceType: this.RESOURCE_TYPE,
            correlationId: account.account_id + ':' + region.region,
            traceId: gs.generateGUID(),
            startedAtMs: startedAtMs
        });
        var runRecordSysId = this._insertDiscoveryRun(runFields);

        var fetchResult;
        try {
            fetchResult = this._fetchLoadBalancers(account, region);
        } catch (fetchEx) {
            gs.error('[HcConnectorElbSync] fetch failed for account=' + account.account_id +
                ' region=' + region.region + ': ' + fetchEx.message);
            this._recordRegionError(region.sys_id, fetchEx.message);
            this._updateDiscoveryRun(runRecordSysId, finishRun(runFields,
                { successCount: 0, failCount: 0, errorSummary: fetchEx.message, endedAtMs: new Date().getTime() }));
            return; // structural guarantee: retirement below is unreachable on fetch failure
        }

        var reconcileResult;
        try {
            reconcileResult = this._reconcileAndUpsert(account, region, fetchResult.loadBalancers);
        } catch (reconcileEx) {
            gs.error('[HcConnectorElbSync] reconcile failed for account=' + account.account_id +
                ' region=' + region.region + ': ' + reconcileEx.message);
            this._recordRegionError(region.sys_id, reconcileEx.message);
            this._updateDiscoveryRun(runRecordSysId, finishRun(runFields,
                { successCount: 0, failCount: fetchResult.loadBalancers.length, errorSummary: reconcileEx.message, endedAtMs: new Date().getTime() }));
            return; // also skip retirement - we don't know which CIs actually got created
        }

        this._updateDiscoveryRun(runRecordSysId, finishRun(runFields, {
            successCount: reconcileResult.summary.insertCount + reconcileResult.summary.refreshCount,
            failCount: 0,
            endedAtMs: new Date().getTime()
        }));
        this._recordRegionSuccess(region.sys_id);
        gs.info('[HcConnectorElbSync] account=' + account.account_id + ' region=' + region.region +
            ' done: ' + JSON.stringify(reconcileResult.summary));
    },

    // ------------------------------------------------------------------
    // Fetch (delegates to HuaweiElbDiscovery)
    // ------------------------------------------------------------------
    _fetchLoadBalancers: function(account, region) {
        var provider = createCredentialProvider(account.auth_mode, {
            propertyReader: function(name) { return gs.getProperty(gs.getCurrentScopeName() + '.' + name); },
            accountId: account.account_id
        });
        var credentials = provider.getCredentials(); // throws NotImplemented for 'agency' - correctly surfaces as a fetch failure above

        var disco = new HuaweiElbDiscovery({
            region: region.region,
            projectId: region.project_id,
            pageLimit: this._getConnectorConfigValue('elb_page_limit', 100),
            maxRetryAttempts: this._getConnectorConfigValue('elb_max_retry_attempts', 3),
            accessKey: credentials.accessKey,
            secretKey: credentials.secretKey
        });

        var loadBalancers = disco.fetchLoadBalancers(); // throws on a page failure - see HuaweiElbDiscovery.js
        return { disco: disco, loadBalancers: loadBalancers };
    },

    // ------------------------------------------------------------------
    // Reconcile (delegates to HuaweiElbDiscovery.reconcileCIs)
    // + upsert HC Resource Sync State + retirement
    // ------------------------------------------------------------------
    _reconcileAndUpsert: function(account, region, loadBalancers) {
        var self = this;

        var disco = new HuaweiElbDiscovery({ region: region.region, accountId: account.account_id });
        var result = disco.reconcileCIs(loadBalancers);

        if (!result) {
            throw new Error('reconcileCIs returned no result - the IRE call likely failed, see the prior gs.error log from HuaweiElbDiscovery');
        }
        if (result.hasError) {
            var totalErrors = (result.items || []).reduce(function(sum, item) { return sum + (item.errorCount || 0); }, 0) +
                (result.relations || []).reduce(function(sum, rel) { return sum + (rel.errorCount || 0); }, 0);
            throw new Error('IRE reconciliation reported errors (errorCount=' + totalErrors + ') - see the prior gs.info log for the full result');
        }

        var seenRecords = loadBalancers.map(function(lb) {
            return { native_key: lb.id, ci: self._lookupCiByCorrelationId(lb.id) };
        });

        var existingRows = this._getExistingSyncStateRows(account.sys_id, region.sys_id);
        var plan = planSyncStateUpdates(seenRecords, existingRows, {
            computeNextState: computeNextState,
            consecutiveMissThreshold: this._getConsecutiveMissThreshold()
        });

        this._applyInserts(account, region, plan.toInsert);
        this._applyRefreshes(plan.toRefresh);
        this._applyTransitions(plan.toTransition);

        return { plan: plan, summary: summarizePlan(plan) };
    },

    _lookupCiByCorrelationId: function(correlationId) {
        var gr = new GlideRecord('cmdb_ci_cloud_load_balancer');
        gr.addQuery('correlation_id', correlationId);
        gr.query();
        if (gr.next()) return gr.getUniqueValue();
        return null;
    },

    // ------------------------------------------------------------------
    // HC Resource Sync State reads/writes - identical to HcConnectorEcsSync's
    // ------------------------------------------------------------------
    _getExistingSyncStateRows: function(accountSysId, regionSysId) {
        var results = [];
        var gr = new GlideRecord(this.SYNC_STATE_TABLE);
        gr.addQuery('account', accountSysId);
        gr.addQuery('region', regionSysId);
        gr.addQuery('resource_type', this.RESOURCE_TYPE);
        gr.query();
        while (gr.next()) {
            results.push({
                sys_id: gr.getUniqueValue(),
                native_key: gr.getValue('native_key'),
                status: gr.getValue('status'),
                consecutive_miss_count: parseInt(gr.getValue('consecutive_miss_count'), 10) || 0
            });
        }
        return results;
    },

    _applyInserts: function(account, region, toInsert) {
        var self = this;
        toInsert.forEach(function(entry) {
            var gr = new GlideRecord(self.SYNC_STATE_TABLE);
            gr.initialize();
            gr.account = account.sys_id;
            gr.region = region.sys_id;
            gr.resource_type = self.RESOURCE_TYPE;
            gr.native_key = entry.native_key;
            if (entry.ci) gr.ci = entry.ci;
            gr.last_seen = new GlideDateTime();
            gr.consecutive_miss_count = 0;
            gr.status = 'active';
            gr.insert();
        });
    },

    _applyRefreshes: function(toRefresh) {
        var self = this;
        toRefresh.forEach(function(entry) {
            var gr = new GlideRecord(self.SYNC_STATE_TABLE);
            if (!gr.get(entry.sys_id)) return;
            if (entry.ci) gr.ci = entry.ci;
            gr.last_seen = new GlideDateTime();
            gr.consecutive_miss_count = 0;
            gr.status = 'active';
            gr.update();
        });
    },

    _applyTransitions: function(toTransition) {
        var self = this;
        toTransition.forEach(function(entry) {
            var gr = new GlideRecord(self.SYNC_STATE_TABLE);
            if (!gr.get(entry.sys_id)) return;
            var ciSysId = gr.getValue('ci');
            gr.status = entry.status;
            gr.consecutive_miss_count = entry.consecutive_miss_count;
            gr.update();

            if (entry.justRetired && ciSysId) {
                self._retireCi(ciSysId);
            }
        });
    },

    _retireCi: function(ciSysId) {
        var retiredValue = this._getRetiredInstallStatusValue();
        if (retiredValue == null) {
            gs.warn('[HcConnectorElbSync] could not resolve cmdb_ci.install_status "Retired" choice value - CI ' +
                ciSysId + ' was retired in HC Resource Sync State but NOT in CMDB, fix manually');
            return;
        }
        var gr = new GlideRecord('cmdb_ci');
        if (!gr.get(ciSysId)) return;
        gr.install_status = retiredValue;
        gr.update();
        gs.info('[HcConnectorElbSync] retired CI ' + ciSysId);
    },

    _getRetiredInstallStatusValue: function() {
        var gr = new GlideRecord('sys_choice');
        gr.addQuery('name', 'cmdb_ci');
        gr.addQuery('element', 'install_status');
        gr.addQuery('label', 'Retired');
        gr.query();
        if (gr.next()) return gr.getValue('value');
        return null;
    },

    // ------------------------------------------------------------------
    // HC Discovery Run reads/writes - identical to HcConnectorEcsSync's
    // ------------------------------------------------------------------
    _insertDiscoveryRun: function(runFields) {
        var snFields = toServiceNowDiscoveryRunFields(runFields);
        var gr = new GlideRecord(this.RUN_TABLE);
        gr.initialize();
        gr.account = snFields.account;
        gr.region = snFields.region;
        gr.resource_type = snFields.resource_type;
        gr.state = snFields.state;
        gr.started = this._msToGlideDateTime(snFields.started);
        gr.success_count = snFields.success_count;
        gr.fail_count = snFields.fail_count;
        gr.correlation_id = snFields.correlation_id;
        gr.trace_id = snFields.trace_id;
        gr.dry_run = snFields.dry_run;
        return gr.insert();
    },

    _updateDiscoveryRun: function(sysId, runFields) {
        var snFields = toServiceNowDiscoveryRunFields(runFields);
        var gr = new GlideRecord(this.RUN_TABLE);
        if (!gr.get(sysId)) return;
        gr.state = snFields.state;
        if (snFields.ended != null) gr.ended = this._msToGlideDateTime(snFields.ended);
        gr.success_count = snFields.success_count;
        gr.fail_count = snFields.fail_count;
        if (snFields.error_summary) gr.error_summary = snFields.error_summary;
        gr.update();
    },

    _msToGlideDateTime: function(ms) {
        var gdt = new GlideDateTime();
        gdt.setNumericValue(ms);
        return gdt;
    },

    // ------------------------------------------------------------------
    // HC Cloud Account / HC Cloud Region reads + status writes - identical
    // to HcConnectorEcsSync's
    // ------------------------------------------------------------------
    _getActiveAccounts: function() {
        var results = [];
        var gr = new GlideRecord(this.ACCOUNT_TABLE);
        gr.addQuery('active', true);
        gr.query();
        while (gr.next()) {
            results.push({
                sys_id: gr.getUniqueValue(),
                account_id: gr.getValue('account_id'),
                auth_mode: gr.getValue('auth_mode')
            });
        }
        return results;
    },

    _getActiveRegions: function(accountSysId) {
        var results = [];
        var gr = new GlideRecord(this.REGION_TABLE);
        gr.addQuery('account', accountSysId);
        gr.addQuery('active', true);
        gr.addQuery('sync_enabled', true);
        gr.query();
        while (gr.next()) {
            results.push({
                sys_id: gr.getUniqueValue(),
                region: gr.getValue('region'),
                project_id: gr.getValue('project_id')
            });
        }
        return results;
    },

    _recordRegionError: function(regionSysId, message) {
        var gr = new GlideRecord(this.REGION_TABLE);
        if (!gr.get(regionSysId)) return;
        gr.last_error = message;
        gr.update();
    },

    _recordRegionSuccess: function(regionSysId) {
        var gr = new GlideRecord(this.REGION_TABLE);
        if (!gr.get(regionSysId)) return;
        gr.last_success = new GlideDateTime();
        gr.last_error = '';
        gr.update();
    },

    // ------------------------------------------------------------------
    // HC Connector Config reads - identical to HcConnectorEcsSync's
    // ------------------------------------------------------------------
    _getConnectorConfigValue: function(key, defaultValue) {
        var gr = new GlideRecord(this.CONFIG_TABLE);
        gr.addQuery('key', key);
        gr.query();
        if (gr.next()) return gr.getValue('value');
        return defaultValue;
    },

    _getConsecutiveMissThreshold: function() {
        var val = this._getConnectorConfigValue('consecutive_miss_threshold', null);
        if (val == null) return undefined; // let resourceLifecycle's own default apply
        var parsed = parseInt(val, 10);
        return isNaN(parsed) ? undefined : parsed;
    },

    type: 'HcConnectorElbSync'
};
